const room=new LivekitClient.Room({adaptiveStream:true,dynacast:true});const url="ws://127.0.0.1:1230/jajo";let roomToken;let dotnetObject;let videoElement;let videoFrame;export async function Init(object){if(!object){throw new Error("dotnet object is undefined")}dotnetObject=object;videoFrame=document.getElementById("video-container");videoElement=document.getElementById("local-video")}export async function Start(token){roomToken=token;try{await room.prepareConnection(url,roomToken);await room.connect("ws://127.0.0.1:1230/jajo",roomToken);const participant=room.localParticipant;await participant.setScreenShareEnabled(true);return true}catch{return false}}export async function Stop(){const participant=room?.localParticipant;if(!participant)return;await participant.setScreenShareEnabled(false)}